async function takeLock(port: number) {
  // A stopped-and-restarted server can start before the old process has finished dying.
  // Waiting a few seconds turns that race into a pause. A server that is really running is
  // still refused, only later. A hot-reloaded edit never reaches this function a second
  // time in the same process — see the guard at the top of serve().
  for (let wait = 0; wait < 20; wait++) {
    if (!existsSync(LOCK_PATH)) break
    const held = JSON.parse(readFileSync(LOCK_PATH, 'utf8'))
    if (!alive(held.pid) || held.pid === process.pid) break
    if (wait === 19) {
      console.error(`werk: another werk is already serving this repository on port ${held.port} (pid ${held.pid}).`)
      console.error('werk: stop it first, or run in a different directory. One server per .werk.')
      process.exit(1)
    }
    if (wait === 0) console.log(`werk: waiting for pid ${held.pid} to let go of the lock`)
    await sleep(250)
  }

